@Composable fun AiConfigurationScreen(vm:AiConfigurationViewModel,lanVm:LanModelViewModel,localVm:LocalSmallModelViewModel){val catalog by vm.catalog.collectAsStateWithLifecycle();val message by vm.message.collectAsStateWithLifecycle();val syncing by vm.syncingProviderIds.collectAsStateWithLifecycle();val tests by vm.providerTests.collectAsStateWithLifecycle();var tab by remember{mutableIntStateOf(0)};var editing by remember{mutableStateOf<AiProviderProfile?>(null)};var detail by remember{mutableStateOf<AiProviderTestState?>(null)};Column(Modifier.fillMaxSize().padding(12.dp)){Text("AI 配置",style=MaterialTheme.typography.headlineSmall);TabRow(tab){Tab(tab==0,{tab=0},text={Text("提供商")});Tab(tab==1,{tab=1},text={Text("模型")})};if(message.isNotBlank())Text(message,style=MaterialTheme.typography.labelMedium,modifier=Modifier.padding(8.dp));if(tab==0)ProviderList(catalog,syncing,tests,{editing=it},vm::synchronize,vm::testConnection,{detail=it}){editing=AiProviderProfile(name="",baseUrl="")}else ModelList(catalog,syncing,vm::synchronizeAll,vm::selectModel);OpenRouterFreeModelsSection(vm);LanModelSettingsSection(lanVm);LocalSmallModelSettingsSection(localVm);PetSettingsSection()};editing?.let{initial->ProviderEditor(initial,{editing=null}){vm.saveProvider(it);editing=null}};detail?.let{s->AlertDialog(onDismissRequest={detail=null},confirmButton={TextButton({detail=null}){Text("关闭")}},title={Text(s.failure?.let{"连接测试失败 · ${it.kind}"}?:"连接测试通过")},text={Text(s.result?.completeDetail?:s.failure?.completeDetail.orEmpty())})}}

@Composable fun AiConfigurationScreen(vm:AiConfigurationViewModel,lanVm:LanModelViewModel){val catalog by vm.catalog.collectAsStateWithLifecycle();val message by vm.message.collectAsStateWithLifecycle();val syncing by vm.syncingProviderIds.collectAsStateWithLifecycle();val tests by vm.providerTests.collectAsStateWithLifecycle();var tab by remember{mutableIntStateOf(0)};var editing by remember{mutableStateOf<AiProviderProfile?>(null)};var detail by remember{mutableStateOf<AiProviderTestState?>(null)};Column(Modifier.fillMaxSize().padding(12.dp)){Text("AI 配置",style=MaterialTheme.typography.headlineSmall);TabRow(tab){Tab(tab==0,{tab=0},text={Text("提供商")});Tab(tab==1,{tab=1},text={Text("模型")})};if(message.isNotBlank())Text(message,style=MaterialTheme.typography.labelMedium,modifier=Modifier.padding(8.dp));if(tab==0)ProviderList(catalog,syncing,tests,{editing=it},vm::synchronize,vm::testConnection,{detail=it}){editing=AiProviderProfile(name="",baseUrl="")}else ModelList(catalog,syncing,vm::synchronizeAll,vm::selectModel);OpenRouterFreeModelsSection(vm);LanModelSettingsSection(lanVm)};editing?.let{initial->ProviderEditor(initial,{editing=null}){vm.saveProvider(it);editing=null}};detail?.let{s->AlertDialog(onDismissRequest={detail=null},confirmButton={TextButton({detail=null}){Text("关闭")}},title={Text(s.failure?.let{"连接测试失败 · ${it.kind}"}?:"连接测试通过")},text={Text(s.result?.completeDetail?:s.failure?.completeDetail.orEmpty())})}}
@Composable fun OpenRouterFreeModelsSection(vm:AiConfigurationViewModel){val state by vm.freeState.collectAsStateWithLifecycle();val refreshing by vm.freeRefreshing.collectAsStateWithLifecycle();var detail by remember{mutableStateOf(false)};Card(Modifier.fillMaxWidth().padding(vertical=6.dp)){Column(Modifier.padding(12.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=androidx.compose.ui.Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("OpenRouter 免费模型",style=MaterialTheme.typography.titleSmall);Text(if(state.autoManage)"每日自动刷新 · 今日 ${state.freeModels.size} 个 · 上次 ${if(state.lastSyncAt==0L)"从未" else java.text.SimpleDateFormat("MM-dd HH:mm",java.util.Locale.getDefault()).format(java.util.Date(state.lastSyncAt))}" else "自动管理已关闭",style=MaterialTheme.typography.labelSmall)};TextButton(enabled=!refreshing,onClick={vm.refreshFreeModels()}){Text(if(refreshing)"刷新中…" else "立即刷新")}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=androidx.compose.ui.Alignment.CenterVertically){Text("自动管理（每日免费池轮换：新免费自动启用，到期自动关闭）",style=MaterialTheme.typography.labelSmall,modifier=Modifier.weight(1f));Switch(checked=state.autoManage,onCheckedChange=vm::setFreeAutoManage)};if(state.freeModels.isNotEmpty()){Text(if(detail)"收起列表" else "展开今日免费列表（${state.freeModels.size}）",style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.primary,modifier=Modifier.clickable{detail=!detail}.padding(vertical=4.dp));if(detail)Column{state.freeModels.forEach{m->Text("· $m",style=MaterialTheme.typography.labelSmall)}}}}}}
@Composable private fun ProviderList(c:AiProviderCatalog,syncing:Set<String>,tests:Map<String,AiProviderTestState>,edit:(AiProviderProfile)->Unit,sync:(String)->Unit,test:(String)->Unit,show:(AiProviderTestState)->Unit,add:()->Unit){LazyColumn(Modifier.fillMaxSize()){items(c.providers,key={it.id}){p->val state=tests[p.id];ListItem(headlineContent={Text(p.name)},supportingContent={Column{Text("${p.baseUrl}\n${p.credentials.size} 个密钥 · ${p.models.size} 个模型");state?.let{complete->when{complete.running->Text("正在测试模型列表和最小聊天",style=MaterialTheme.typography.labelSmall);complete.result!=null->Text("连接通过 · 点击查看",Modifier.clickable{show(complete)},style=MaterialTheme.typography.labelSmall,color=MaterialTheme.colorScheme.primary);complete.failure!=null->Text("连接失败 ${complete.failure?.kind} · 点击查看",Modifier.clickable{show(complete)},style=MaterialTheme.typography.labelSmall,color=MaterialTheme.colorScheme.error)}}}},trailingContent={Column{TextButton(enabled=p.configured&&p.id !in syncing,onClick={sync(p.id)}){Text(if(p.id in syncing)"同步中" else "同步")};TextButton(enabled=p.configured&&state?.running!=true,onClick={test(p.id)}){Text(if(state?.running==true)"测试中" else "测试")}}},modifier=Modifier.clickable{edit(p)});HorizontalDivider()};item{ListItem(headlineContent={Text("添加提供商")},leadingContent={Icon(Icons.Default.Add,null)},modifier=Modifier.clickable(onClick=add))}}}
@Composable private fun ModelList(c:AiProviderCatalog,syncing:Set<String>,syncAll:()->Unit,select:(String,String)->Unit){LazyColumn(Modifier.fillMaxSize()){item{ListItem(headlineContent={Text("从所有提供商同步")},supportingContent={Text("获取所有已配置 API 的最新模型列表")},leadingContent={Icon(Icons.Default.Refresh,null)},modifier=Modifier.clickable(enabled=syncing.isEmpty(),onClick=syncAll))};c.providers.forEach{p->item{Text(p.name,style=MaterialTheme.typography.titleMedium,modifier=Modifier.padding(top=16.dp,bottom=6.dp))};items(p.models,key={"${p.id}:$it"}){m->val selected=c.defaultModel==AiModelSelection(p.id,m);ListItem(headlineContent={Text(m)},supportingContent={Text(if(selected)"默认模型" else p.name)},leadingContent={RadioButton(selected,{select(p.id,m)})},modifier=Modifier.clickable{select(p.id,m)})}}}}
@Composable private fun ProviderEditor(initial:AiProviderProfile,onDismiss:()->Unit,onSave:(AiProviderProfile)->Unit){var name by remember{mutableStateOf(initial.name)};var url by remember{mutableStateOf(initial.baseUrl)};var chatPath by remember{mutableStateOf(initial.chatPath)};var modelsPath by remember{mutableStateOf(initial.modelsPath)};var headers by remember{mutableStateOf(initial.headersJson)};var credentials by remember{mutableStateOf(initial.credentials)};var thinkingDisplay by remember{mutableStateOf(com.uma.workbench.agent.ThinkingLevels.toDisplayValue(initial.thinkingLevel))};var thinkingMenu by remember{mutableStateOf(false)};var label by remember{mutableStateOf("")};var secret by remember{mutableStateOf("")};var selected by remember{mutableStateOf(initial.selectedCredentialId)};val valid=remember(name,url,chatPath,modelsPath,headers,credentials,selected){runCatching{initial.copy(name=name,baseUrl=url,chatPath=chatPath,modelsPath=modelsPath,headersJson=headers,credentials=credentials,selectedCredentialId=selected).validate()}.isSuccess};AlertDialog(onDismissRequest=onDismiss,title={Text(if(initial.name.isBlank())"添加提供商" else initial.name)},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){item{OutlinedTextField(name,{name=it},label={Text("名称")})};item{OutlinedTextField(url,{url=it},label={Text("基础 URL")})};item{OutlinedTextField(chatPath,{chatPath=it},label={Text("聊天路径")})};item{OutlinedTextField(modelsPath,{modelsPath=it},label={Text("模型列表路径")})};item{OutlinedTextField(headers,{headers=it},label={Text("请求头 JSON")},supportingText={Text("用 {{secret}} 引用当前启用密钥；使用 {} 表示无鉴权")},minLines=3)};item{Box{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=androidx.compose.ui.Alignment.CenterVertically){Text("思考深度");TextButton(onClick={thinkingMenu=true}){Text(thinkingDisplay)}};DropdownMenu(expanded=thinkingMenu,onDismissRequest={thinkingMenu=false}){com.uma.workbench.agent.ThinkingLevels.displayOptions.forEach{opt->DropdownMenuItem(text={Text(opt)},onClick={thinkingDisplay=opt;thinkingMenu=false})}}}};items(credentials,key={it.id}){key->Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Row(Modifier.weight(1f)){RadioButton(selected==key.id,{selected=key.id});Column(Modifier.weight(1f)){Text(key.label);OutlinedTextField(key.secret,{value->credentials=credentials.map{if(it.id==key.id)it.copy(secret=value)else it}},label={Text("API 密钥完整原值")},modifier=Modifier.fillMaxWidth())}};TextButton({credentials=credentials.filterNot{it.id==key.id};if(selected==key.id)selected=null}){Text("删除")}}};item{OutlinedTextField(label,{label=it},label={Text("密钥名称")});OutlinedTextField(secret,{secret=it},label={Text("API 密钥完整原值")});TextButton(enabled=label.isNotBlank()&&secret.isNotBlank(),onClick={val key=AiApiCredential(label=label,secret=secret);credentials+=key;if(selected==null)selected=key.id;label="";secret=""}){Text("添加密钥")}}}},confirmButton={TextButton(onClick={onSave(initial.copy(name=name,baseUrl=url,chatPath=chatPath,modelsPath=modelsPath,headersJson=headers,credentials=credentials,selectedCredentialId=selected,thinkingLevel=com.uma.workbench.agent.ThinkingLevels.toRequestValue(thinkingDisplay)))},enabled=valid){Text("保存")}},dismissButton={TextButton(onDismiss){Text("取消")}})}
